PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS TB_TRABAJADOR(idTbj INTEGER PRIMARY KEY,nombreTbj TEXT NOT NULL,usuarioTbj TEXT NOT NULL UNIQUE,contrasenaTbj TEXT NOT NULL,tipoTbj TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS TB_CLIENTE(rucCli INTEGER PRIMARY KEY,nombreCli TEXT NOT NULL,razonCli TEXT NOT NULL,correoCli TEXT);
CREATE TABLE IF NOT EXISTS TB_PRODUCTO(codPro INTEGER PRIMARY KEY,descripPro TEXT NOT NULL,precioUPro REAL NOT NULL CHECK(precioUPro>=0),stockPro INTEGER NOT NULL CHECK(stockPro>=0),tipoPro TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS TB_PROVEEDOR(codProve INTEGER PRIMARY KEY,nombreProve TEXT NOT NULL,codProd INTEGER NOT NULL REFERENCES TB_PRODUCTO(codPro));
CREATE TABLE IF NOT EXISTS TB_FACTURA(codFact INTEGER PRIMARY KEY,fechaEFact TEXT NOT NULL,rucClien INTEGER NOT NULL REFERENCES TB_CLIENTE(rucCli),idTbja INTEGER NOT NULL REFERENCES TB_TRABAJADOR(idTbj));
CREATE TABLE IF NOT EXISTS TB_VENTA_PRODUCTO(codFac INTEGER NOT NULL REFERENCES TB_FACTURA(codFact),codProd INTEGER NOT NULL REFERENCES TB_PRODUCTO(codPro),cantidad INTEGER NOT NULL CHECK(cantidad>0),precioVenta REAL NOT NULL CHECK(precioVenta>=0),PRIMARY KEY(codFac,codProd));
